 ts={};f={}
 for site,ns in zip(s,nbs):
  if site.specie.symbol not in ['Be','Mg','Zn','Cd','Hg','B','Al','Ga','In','Si','Ge','Sn','P','As','Sb','C','Cu','Ag','Li']:continue
  if site.specie.symbol=='Li':continue
  ns=[n for n in ns if n.specie.X>site.specie.X and n.nn_distance<1.25*(covalent_radii[site.specie.Z]+covalent_radii[n.specie.Z])]
