 for st in ['T','mass','X','Z']:
  if st in f:
   v=f.pop(st);f[st+'_amp']=np.max(abs(v));f[st+'_norm']=np.linalg.norm(v)
 if 'dist' in f:f.pop('dist')
 bf.append(f);tensors.append(ts)
